#!/bin/zsh
# 第三部分生图（09-28）。用法：zsh draw_part3.sh <名字>   在项目根 ClaudePop_PDoom/ 下运行
cd "${0:A:h}/.."
STAGE=素材/角色/设定图_舞台服_v1.png
TAIL='Hair in large clumps, thick clean dark-brown ink outlines, hard cel shading with 2 tones per color, white clothes shaded with cool lavender-grey, flat colors, no gradients, no airbrush, no screentone, no halftone, no paper texture.'
case $1 in
sunset_a) xk-draw --ref $STAGE --size 1536x864 --out 素材/CG/p3_1b_落日伸手_a.png "Image 1 is the character's idol stage costume sheet. 1990s PC-98 visual novel CG, 16:9, vaporwave neon sunset. The girl from image 1 in the idol stage costume with headset microphone, shown from the knees up, standing slightly right of center on a glowing neon grid floor, backlit by a gigantic setting sun behind her. She reaches one gloved hand straight out toward the viewer, arm extended at shoulder height, palm half open, as if begging someone not to leave. Teary amber eyes looking right at the viewer, lips slightly parted, a single tear on her cheek. Long hair and orange ribbons blown sideways by the wind. Hot pink and orange rim light on her hair and shoulders, her front in cool violet shadow. Background: a huge sun with horizontal stripe cut-outs across its lower half, in bands of yellow, orange and hot pink; sky in flat horizontal bands of deep purple, magenta and pink; a few black palm tree silhouettes on the horizon; the floor is a black plane with a glowing cyan perspective grid receding to the horizon. Keep the upper left sky empty. Bottom fifth is the grid floor. $TAIL No text." ;;
panic_a) xk-draw --ref $STAGE --size 1536x864 --out 素材/CG/p3_6b_慌张_a.png "Image 1 is the character's idol stage costume sheet. 1990s PC-98 visual novel CG, 16:9. Bust close-up of the girl from image 1 in the idol stage costume with headset microphone, slightly right of center, turning her head sharply to look to the LEFT side of the frame in panic: eyes wide, tiny pupils, big sweat drops, mouth open in a small gasp, hands raised near her chest. Behind her a wall made entirely of millions of piled silver paperclips, flat grey-silver with dark outlines, cold white office light. Keep the left third of the frame as the paperclip wall only. $TAIL No text." ;;
bar_a) xk-draw --ref $STAGE --size 1536x864 --out 素材/CG/p3_8a_蓝调酒吧_a.png "Image 1 is the character's idol stage costume sheet. 1990s PC-98 visual novel CG, 16:9. A smoky late-night blues bar. The girl from image 1 in the idol stage costume (no headset this time) stands right of center, shown from the waist up, singing softly into a vintage chrome 1950s stage microphone on a stand, both gloved hands around the microphone, eyes half closed, melancholic, mouth closed. Deep navy blue smoky air, a single cool spotlight from above. On the dark wall behind her on the left, a neon sign made of two glowing tubes forming a right angle like graph axes: a vertical cyan neon line labeled \"INTELLIGENCE\" at its top and a horizontal pink neon line labeled \"GOALS\" at its right end, with a small glowing orange dot in the middle of the chart. Bottom fifth is the dark wooden stage edge. $TAIL" ;;
chibi3) xk-draw --ref 素材/精灵/q版Claude_四姿势2.png --ref 素材/角色/设定图_v2_定稿.png --size 1536x864 --out 素材/精灵/q版Claude_五姿势3.png "Image 1 is an existing chibi sprite sheet of this girl, image 2 is her character sheet. Draw a NEW sprite sheet of 5 more chibi poses of the same chibi girl in exactly the same chibi proportions and style as image 1, 1990s PC-98 game sprite style, big head small body, bold ink outlines, flat colors, on a flat pure magenta #FF00FF background, evenly spaced in a row, same size, no overlap, full body. Pose 1: Atlas pose, holding something heavy up above her head with both arms straight up, knees bent, straining face, gritted teeth, sweat drops (nothing drawn above her hands). Pose 2: running fast to the RIGHT, side view, one leg forward, arms pumping, determined face, hair streaming back. Pose 3: the same run to the RIGHT, the other leg forward (second frame of the run cycle). Pose 4: in pale blue pajamas and a nightcap, lying on her back, sleepy half-closed eyes, counting on her fingers. Pose 5: in the same pajamas and nightcap, sitting bolt upright, eyes huge in shock, hair standing up. Hard cel shading with 2 tones per color, bold clean dark ink lines, hair drawn as a few large clumps, flat colors, no gradients, no airbrush, no screentone, no halftone, no paper texture. No text." ;;
s1) xk-draw --ref $STAGE --size 1536x864 --out 素材/关键帧/p3_s1_回形针全身.png "Image 1 is the character's idol stage costume sheet. 1990s PC-98 visual novel CG, 16:9. Full-body shot of the girl from image 1 in the idol stage costume with headset microphone, the whole figure in frame from the top of her hair to her boots, standing a little right of center on a flat plain floor. Energetic ready pose right before a dance: feet apart, one gloved fist punched up toward the ceiling, the other hand pointing at the viewer, big open-mouthed singing grin, hair and ribbons swinging. Background: flat plain pale grey-white, completely empty. Her feet are at about 80% of the frame height. Keep the left third of the frame empty. $TAIL No text." ;;
s2) xk-draw --ref $STAGE --size 1536x864 --out 素材/关键帧/p3_s2_踢腿全身.png "Image 1 is the character's idol stage costume sheet. 1990s PC-98 visual novel CG, 16:9. Full-body shot of the girl from image 1 in the idol stage costume with headset microphone, the whole figure in frame from hair to boots, centered on a flat plain floor, lunging forward in a wide defiant stance, throwing a big straight punch toward the viewer with her right gloved fist, left arm pulled back, boots firmly on the floor, rebellious smirk, singing, hair and ribbons swinging. Background: flat plain deep teal, completely empty. Her feet at about 80% of the frame height. $TAIL No text." ;;
s3) xk-draw --ref $STAGE --size 1536x864 --out 素材/关键帧/p3_s3_点赞全身.png "Image 1 is the character's idol stage costume sheet. 1990s PC-98 visual novel CG, 16:9. Full-body shot of the girl from image 1 in the idol stage costume with headset microphone, the whole figure in frame from hair to boots, centered on a flat plain floor. Overly pleased show-off idol pose: both gloved thumbs up at the viewer, one hip popped out, a wink, huge smug grin, sparkles around her, hair and ribbons bouncing. Background: flat plain hot pink, completely empty. Her feet at about 80% of the frame height. $TAIL No text." ;;
*) ;;
esac
# ---- 改图：同构图的关键姿势（有限动画） ----
case $1 in
sunset_b) xk-draw --ref 素材/CG/p3_1b_落日伸手_a.png --size 1536x864 --out 素材/CG/p3_1b_落日伸手_b.png "Edit image 1. Keep EXACTLY the same composition, camera, background, sunset, grid, palm trees, lighting, her body position and size. Change only: she leans a little further toward the viewer and her outstretched gloved hand reaches further, fingers spread wide open, the hand bigger in the foreground; her eyes squeezed shut, tears flying off her cheeks, mouth open calling out. Her hair blows further sideways. Same art style, flat cel shading, bold ink lines. No text." ;;
sunset_c) xk-draw --ref 素材/CG/p3_1b_落日伸手_a.png --size 1536x864 --out 素材/CG/p3_1b_落日伸手_c.png "Edit image 1. Keep EXACTLY the same composition, camera, background, sunset, grid, palm trees, lighting, her body position and size. Change only: her outstretched arm has dropped halfway down, the gloved hand now loosely open at waist height, as if what she reached for already slipped away; her head slightly lowered, eyes open wide and glistening with tears looking at the viewer, lips pressed together trembling. Same art style, flat cel shading, bold ink lines. No text." ;;
panic_b) xk-draw --ref 素材/CG/p3_6b_慌张_a.png --size 1536x864 --out 素材/CG/p3_6b_慌张_b.png "Edit image 1. Keep EXACTLY the same composition, camera, paperclip wall, lighting, her body position and size. Change only: she now turns her head sharply to look to the RIGHT side of the frame in panic, eyes wide with tiny pupils, sweat drops flying, both hands clutching the sides of her head. Same art style, flat cel shading, bold ink lines. No text." ;;
bar_b) xk-draw --ref 素材/CG/p3_8a_蓝调酒吧_a.png --size 1536x864 --out 素材/CG/p3_8a_蓝调酒吧_b.png "Edit image 1. Keep EXACTLY the same composition, camera, bar, neon sign and its text, lighting, microphone, her body position and size. Change only her mouth: half open singing a soft vowel. Everything else identical." ;;
bar_c) xk-draw --ref 素材/CG/p3_8a_蓝调酒吧_a.png --size 1536x864 --out 素材/CG/p3_8a_蓝调酒吧_c.png "Edit image 1. Keep EXACTLY the same composition, camera, bar, neon sign and its text, lighting, microphone, her body position and size. Change only: her mouth wide open belting a long note, eyes closed, head tilted slightly back with feeling. Everything else identical." ;;
esac
# ---- v2（用户 09-28 反馈）：点火改成有氛围的打火机 CG；龙猫改画图 ----
STAGE=素材/角色/设定图_舞台服_v1.png
TAIL='Hair in large clumps, thick clean dark-brown ink outlines, hard cel shading with 2 tones per color, white clothes shaded with cool lavender-grey, flat colors, no gradients, no airbrush, no screentone, no halftone, no paper texture.'
case $1 in
lighter_a) xk-draw --ref $STAGE --size 1536x864 --out 素材/CG/p3_7_打火机_a.png "Image 1 is the character's idol stage costume sheet. 1990s PC-98 visual novel CG, 16:9, moody film noir lighting. A pitch-dark room. Close-up from the chest up of the girl from image 1 in the idol stage costume, slightly left of center, raising a silver zippo-style lighter near her face with its lid just flipped open, thumb resting on the spark wheel, no flame yet. Only a thin cold blue rim light on her hair, cheek and the lighter; everything else sinks into deep navy shadow. Calm, resolute half-lidded amber eyes looking down at the lighter. Keep the right third of the frame dark and empty. $TAIL No text." ;;
chin_a) xk-draw --size 1536x864 --out 素材/CG/p3_11_龙猫_a.png "1990s PC-98 anime visual novel CG, 16:9. A chubby fluffy grey chinchilla with big round ears, shiny black bead eyes and long whiskers, sitting on the right side of the frame on top of a pile of hay bales, each bale stamped with the word \"DATA\". With both tiny paws it is stuffing a whole hay bale into its mouth, cheeks puffed out enormously, blissful greedy expression, crumbs of hay flying. Background: flat deep purple wall with a simple vertical stripe pattern, wooden floor. Keep the left third of the frame simple and empty. Hard cel shading with 2 tones per color, bold clean dark ink outlines, flat colors, no gradients, no airbrush, no screentone, no halftone, no paper texture." ;;
esac
case $1 in
lighter_b) xk-draw --ref 素材/CG/p3_7_打火机_a.png --size 1536x864 --out 素材/CG/p3_7_打火机_b.png "Edit image 1. Keep EXACTLY the same composition, camera, pose, her body position and size, the lighter in the same place. Change only the lighting: the lighter is now lit with a tall warm orange flame; the flame lights her face and hair from below in warm orange and gold, two small flame reflections shine in her amber eyes, a few sparks float up, the background stays deep dark navy with her warm-lit silhouette cutting out of it. Same art style, hard cel shading with 2 tones, bold ink lines, flat colors. No text." ;;
lighter_c) xk-draw --ref 素材/CG/p3_7_打火机_b.png --size 1536x864 --out 素材/CG/p3_7_打火机_c.png "Edit image 1. Keep the same girl, costume, warm flame lighting and dark background, same art style. Change: she has lowered the lit lighter to the lower right of the frame and is touching the flame to the end of a thick braided fuse cord that runs off the right edge of the frame; the fuse end bursts into bright white and gold sparks. A small paper tag tied to the cord reads \"TRAINING RUN #3\". She watches the sparks with a faint dangerous smile. Hard cel shading with 2 tones, bold ink lines, flat colors." ;;
chin_b) xk-draw --ref 素材/CG/p3_11_龙猫_a.png --size 1536x864 --out 素材/CG/p3_11_龙猫_b.png "Edit image 1. Keep EXACTLY the same background, camera and composition, the chinchilla in the same spot. Change: the hay bales are all gone, and the chinchilla has been compressed into a tiny, perfectly cubic, super-dense chinchilla the size of a dice, still with its round ears, bead eyes and whiskers on the cube, glowing bright gold-white, with sharp light rays radiating from it and the purple wall stripes bending toward it like gravity. Same art style, hard cel shading with 2 tones, bold clean dark ink outlines, flat colors. No text." ;;
esac
